head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징


scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIsurCd;
scwin.gCOM_NM;
scwin.gSchDate;
scwin.gDtecDate;
scwin.vScrenID = 'ULDSTF37405.xml';
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?");

    //alert(url +"     =      "+ arr);		
    return (arr.length > 1 ? arr[1] : '');
};



//페이지 로딩 시 필요한 변수 초기화
scwin.fn_SetCode = function() {
    if (scwin.fn_GetProvider() == 'POPUPMODE') {
        //조회일자 셋팅
        edt_SchDate.setValue(scwin.gSchDate);


        //회사코드 셋팅
        txb_isur_cd.setValue(scwin.gIsurCd);
        txb_com_abbrv.setValue(scwin.gCOM_NM);
    } else {
        //조회일자 오늘로 셋팅
        var vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SchDate.setValue(vCurDate);
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !정보--;
셋팅-- > function() {
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd; // 법인코드				
    scwin.gCOM_NM = $c.frame.path("../").gComAbbrv; // 회사명
    scwin.gSchDate = $c.frame.path("../").scwin.gSchDate; // 조회일자
    scwin.gDtecDate = $c.frame.path("../").scwin.gDtecDate; // 적출일자

};
scwin.fn_Search = function() {
    var vISUR_CD = $c.stf.getObjectValue(txb_isur_cd);
    var vSCH_DD = $c.stf.getObjectValue(edt_SchDate);
    var url = "/ByPass.do?method=listInvstcautnRemndKosdaq";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&SCH_DD=" + vSCH_DD;
    url += "&DTEC_DD=" + scwin.gDtecDate;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);

        // 조회대상기간(조회일 기준 최근3년)
        var sch_full_dt = edt_SchDate.getValue();
        var sch_yy = sch_full_dt.substr(0, 4);
        var sch_mm = sch_full_dt.substr(4, 2);
        var sch_dd = sch_full_dt.substr(6, 2);
        var kosdaq_yy = scwin.gDtecDate.substr(0, 4) - 3;
        var to_sch_yy = sch_yy - 3;
        tbx_sch_period.setValue(+kosdaq_yy + "-07-01" + " ~ " + sch_yy + "-" + sch_mm + "-" + sch_dd);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_SchDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "투자주의 환기종목 지정 현황(최근3년)", "", "8");
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    fn_GetParentValue();
    scwin.fn_SetCode();

    //회사정보 로딩
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Search();
};
